import logging
import os
from time import sleep
from jsilib.jsonrpc.exc import ClientClosedError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def _create_logger(**kwargs):
    file_path = kwargs.get('file_path', os.path.join(os.path.expanduser('~'), 'jsilib.logs'))
    log_level = kwargs.get('log_level', 'INFO')

    logger = logging.getLogger('jsilib')
    level = getattr(logging, log_level)
    logger.setLevel(level)

    file_handler = logging.FileHandler(file_path, 'w')

    file_handler.setLevel(logging.DEBUG)

    formatter = logging.Formatter('%(levelname)s - %(asctime)s - [%(name)s] %(message)s')
    file_handler.setFormatter(formatter)
    logger.addHandler(file_handler)

    return logger


def reconnect(func):
    def decorator(self, *args, **kwargs):
        try:
            return func(self, *args, **kwargs)
        except ClientClosedError:
            self.disconnect()
            wait_time = 20
            logger.info(
                "Connection was closed on server side, waiting {}s and attempting reconnect ...".format(wait_time)
            )
            sleep(wait_time)
            self._fdsw_interface._client.setup()
            self._fdsw_interface._client.connect()
            return func(self, *args, **kwargs)
    return decorator
